import json

def add_after(path, anchor_key, inserts):
    data = json.load(open(path))
    def walk(obj):
        if isinstance(obj, dict):
            if anchor_key in obj:
                items = list(obj.items())
                out = {}
                for k, v in items:
                    out[k] = v
                    if k == anchor_key:
                        for nk, nv in inserts:
                            if nk not in obj:
                                out[nk] = nv
                obj.clear(); obj.update(out)
            for v in obj.values():
                walk(v)
        elif isinstance(obj, list):
            for v in obj: walk(v)
    walk(data)
    with open(path, "w") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")

