import json

RENAMES = {
    "strings.json": {
        "min_soc": "Minimum ESS SoC (%)",
        "max_soc": "Maximum ESS SoC (%)",
        "soc_sensor": "ESS battery SoC sensor",
    },
    "en.json": {
        "min_soc": "Minimum ESS SoC (%) — the home storage, not the EV",
        "max_soc": "Maximum ESS SoC (%) — the home storage, not the EV",
        "soc_sensor": "ESS battery SoC sensor (home storage)",
    },
    "pl.json": {
        "min_soc": "Minimalny SoC magazynu (%) — ESS, nie EV",
        "max_soc": "Maksymalny SoC magazynu (%) — ESS, nie EV",
        "soc_sensor": "Sensor SoC magazynu (ESS)",
    },
}

def rename(path, mapping):
    data = json.load(open(path))
    count = 0
    def walk(obj):
        nonlocal count
        if isinstance(obj, dict):
            for k in list(obj):
                if k in mapping and isinstance(obj[k], str):
                    obj[k] = mapping[k]
                    count += 1
                walk(obj[k])
        elif isinstance(obj, list):
            for v in obj:
                walk(v)
    walk(data)
    with open(path, "w") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print(path, count)

rename("custom_components/powerpilot/strings.json", RENAMES["strings.json"])
rename("custom_components/powerpilot/translations/en.json", RENAMES["en.json"])
rename("custom_components/powerpilot/translations/pl.json", RENAMES["pl.json"])
EOF

